var HMG = (function () {
  'use strict';
  var MOUTHS = 10;  // ship's company of ten: skipper + five named crew + four hired hands (Aifur-class canon, Nov 23 lock)
  var FREEZE = 32;   // May 11: the early southbound convoys leave the landing (game clock, tuned for play)
  var WINTER = 44;   // May 23: the Kiev road closes — the June gathering can no longer be made (guard)
  var VILLAGE_P = 55;
  var FLEET = 90;      // Jul 8: the June gathering's fleet finally clears Kiev — arrive later and you run the rapids alone (round-37 sign-off; day counts design-tuned)
  var SEACLOSE = 138;  // Aug 25: the summons stops coming at Cherson — the Black Sea closes to late hulls

  function rand(s) {
    var a = (s.rngS = (s.rngS + 0x6d2b79f5) | 0);
    var t = Math.imul(a ^ (a >>> 15), a | 1);
    t = (t + Math.imul(t ^ (t >>> 7), t | 61)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  function find(s, name) {
    for (var i = 0; i < s.crew.length; i++) if (s.crew[i].name === name) return s.crew[i];
    return null;
  }

  function newRun(seed) {
    return {
      v: 1, phase: 'intro', day: 1, progress: 0,
      food: 140, silver: 8, hull: 100, morale: 7, wet: 0,
      crew: [
        { name: 'Ketil', role: 'boatswain', hp: 2, dead: false, graveF: 2 },
        { name: 'Halfr', role: 'oarsman', hp: 2, dead: false, graveF: 2 },
        { name: 'Orm', role: 'oarsman', hp: 2, dead: false, graveF: 2 },
        { name: 'Groa', role: 'cook', hp: 2, dead: false, graveF: 2 },
        { name: 'Ottar', role: 'bowman', hp: 2, dead: false, graveF: 2 },
        { name: 'Vifil', role: 'keel-hand', hp: 2, dead: false, graveF: 2 },
        { name: 'Hrafn', role: 'keel-hand', hp: 2, dead: false, graveF: 2 },
        { name: 'Steinarr', role: 'keel-hand', hp: 2, dead: false, graveF: 2 },
        { name: 'Dyri', role: 'keel-hand', hp: 2, dead: false, graveF: 2 }
      ],
      sick: { stage: 0, next: 0, resolved: true },
      leg: 1, furs: 0, captives: 0, freight: 0,
      flags: { storm: false, squall: false, village: false, rested: false, feasted: false, w1: false, lowwater: false, portage: false },
      lastEv: [], pending: null, result: null,
      rngS: (seed >>> 0) || 12345
    };
  }

  function dateStr(d) {  // day 1 = Apr 10 from Birka; one season to the Black Sea (verify-leg2 pins Apr-May, verify-leg3 pins Jun-Sep)
    if (d <= 21) return 'Apr ' + (d + 9);
    if (d <= 52) return 'May ' + (d - 21);
    if (d <= 82) return 'Jun ' + (d - 52);
    if (d <= 113) return 'Jul ' + (d - 82);
    if (d <= 144) return 'Aug ' + (d - 113);
    return 'Sep ' + (d - 144);
  }

  var aliveCrew = function (s) { return s.crew.filter(function (c) { return !c.dead; }).length; };
  // living hands drive the ship: full company = 1.0, each death slows her, floor at half speed
  function crewFactor(s) { return Math.max(0.5, (1 + aliveCrew(s)) / 10); }
  function adj(s, f) {
    if (f.food) s.food = Math.max(0, s.food + f.food);
    if (f.silver) s.silver = Math.max(0, s.silver + f.silver);
    if (f.hull) s.hull = Math.min(100, Math.max(0, s.hull + f.hull));
    if (f.morale) s.morale = Math.min(10, Math.max(0, s.morale + f.morale));
    if (f.progress) s.progress = Math.min(100, s.progress + f.progress * crewFactor(s));
    if (f.wet) s.wet = s.wet + f.wet;
  }

  var POOL = [
    { id: 'fair' }, { id: 'calm' }, { id: 'fog' }, { id: 'seals' },
    { id: 'chud', need: function (s) { return s.silver >= 1; } },
    { id: 'seam' }, { id: 'rain' }, { id: 'aurora' }
  ];
  // second leg — the Volkhov upriver pool (no seals, no log-boats with smoked lake fish)
  var RIVER = [
    { id: 'fair' }, { id: 'rain' }, { id: 'aurora' }, { id: 'fog' }, { id: 'seam' },
    { id: 'nets' }, { id: 'hearth' }
  ];
  // the Greek sea run: round-1 placeholder deck (build round 4 gives the sea its own weather)
  // build round 4: the Greek sea run (Cherson to Miklagard) — the summons wait, the escort, the coastal storm, Mesembria, St Aitherios
  var SEA3 = [ { id: 'fair' }, { id: 'rain' }, { id: 'fog' }, { id: 'seam' }, { id: 'cstorm' } ];
  // build round 2 (his go, per the signed brief): the real decks — the Lovat/portage subleg and the Dnieper subleg
  var LOVAT3 = [
    { id: 'fair' }, { id: 'rain' }, { id: 'fog' }, { id: 'seam' },
    { id: 'nets' }, { id: 'hearth' },   // the quiet-water and shingle-camp events wear well on the Lovat too (round 24 numbers)
    { id: 'ilmenstorm' },
    { id: 'hoard', need: function (s) { return s.silver >= 3; } }   // the share of the rumor costs 3 dirhams
  ];
  var DNIPR3 = [
    { id: 'fair' }, { id: 'rain' }, { id: 'fog' }, { id: 'seam' },
    { id: 'tailwind' },
    { id: 'fmarket', need: function (s) { return s.silver >= 2; } },
    { id: 'ferry', need: function (s) { return s.silver >= 2; } },
    { id: 'kinsman' }
  ];
  // build round 3: the rapids road (Kiev to Cherson) — seven rapids as set pieces, Nenasytets the big one,
  // Pecheneg parley per the round-37 lock: NO WAR, but a fumbled parley is a lethal EVENT (crew members die where they stand)
  var RAPIDS3 = [
    { id: 'fair' }, { id: 'rain' }, { id: 'fog' }, { id: 'seam' },
    { id: 'parley', need: function (s) { return !s.flags.l3Parley; } }   // the horsemen come down once to the bank
  ];
  var HIRES = ['Audun', 'Thorstein', 'Ragnvald', 'Sverting'];  // hub hire pool, paid from the settlement purse
  var HOLD = 12;  // hold units: 1 per fur bale, 2 per captive

  function drawMorning(s) {
    // leg three runs the southern water-road: round-1 placeholder decks per subleg (the real rosters land with build rounds 2-4)
    if (s.leg === 3) {
      if (s.sub === 1) {   // the Lovat shallows and the watershed portage are the subleg's spine, each once
        if (!s.flags.l3Lovat && s.progress >= 30) { s.flags.l3Lovat = true; return { id: 'lovat' }; }
        if (!s.flags.l3Port && s.progress >= 70) { s.flags.l3Port = true; return { id: 'portage3' }; }
      }
      if (s.sub === 4) {   // build round 4: the sea run's spine — the summons, the escort, Mesembria, St Aitherios
        if (!s.flags.l3Summ && s.progress < 12) { s.flags.l3Summ = true; return { id: 'summons' }; }
        if (!s.flags.l3Esc && s.progress >= 35) { s.flags.l3Esc = true; return { id: 'escort' }; }
        if (!s.flags.l3Mes && s.progress >= 60) { s.flags.l3Mes = true; return { id: 'mesembria' }; }
        if (!s.flags.l3Aith && s.progress >= 82) { s.flags.l3Aith = true; return { id: 'statherios' }; }
      }
      if (s.sub === 3) {   // build round 3: the rapids road's spine — the first rapids, Nenasytets, Khortytsia, the delta
        if (!s.flags.l3Rap && s.progress >= 20) { s.flags.l3Rap = true; return { id: 'rapids1' }; }
        if (!s.flags.l3Nen && s.progress >= 40) { s.flags.l3Nen = true; return { id: 'nenasytets' }; }
        if (!s.flags.l3Khor && s.progress >= 60) { s.flags.l3Khor = true; return { id: 'khortytsia' }; }
        if (!s.flags.l3Delta && s.progress >= 82) { s.flags.l3Delta = true; return { id: 'delta' }; }
      }
      var pool3 = (s.sub === 4) ? SEA3 : (s.sub === 2) ? DNIPR3 : (s.sub === 3) ? RAPIDS3 : LOVAT3;
      var elig3 = pool3.filter(function (e) { return (!e.need || e.need(s)) && s.lastEv.indexOf(e.id) < 0; });
      if (!elig3.length) elig3 = pool3;
      var pick3 = elig3[Math.floor(rand(s) * elig3.length)];
      if (pick3.id === 'parley') s.flags.l3Parley = true;   // once the horsemen have come, they do not come again
      s.lastEv.push(pick3.id);
      s.lastEv = s.lastEv.slice(-2);
      return { id: pick3.id };
    }
    // the river leg has its own deck: no lake squalls, no Halfr arc — instead the water-level gate and the portage
    if (s.leg === 2) {
      if (!s.flags.lowwater && s.progress >= 40) { s.flags.lowwater = true; return { id: 'lowwater' }; }
      if (!s.flags.portage && s.progress >= 70) { s.flags.portage = true; return { id: 'portage' }; }
      var elig2 = RIVER.filter(function (e) {
        return (!e.need || e.need(s)) && s.lastEv.indexOf(e.id) < 0;
      });
      var pick2 = elig2[Math.floor(rand(s) * elig2.length)];
      s.lastEv.push(pick2.id);
      s.lastEv = s.lastEv.slice(-2);
      return { id: pick2.id };
    }
    var halfr = find(s, 'Halfr');
    if (halfr && halfr.dead) s.sick.resolved = true;
    if (!s.flags.w1 && s.day >= 4) { s.flags.w1 = true; return { id: 'w1' }; }
    if (s.sick.stage === 2 && !s.sick.resolved && s.day >= s.sick.next) return { id: 'w2' };
    if (!s.flags.storm && s.day >= 3) { s.flags.storm = true; return { id: 'storm' }; }
    if (!s.flags.squall && s.progress >= 85 && s.day >= 24) { s.flags.squall = true; return { id: 'squall' }; }
    var elig = POOL.filter(function (e) {
      return (!e.need || e.need(s)) && s.lastEv.indexOf(e.id) < 0;
    });
    var pick = elig[Math.floor(rand(s) * elig.length)];
    s.lastEv.push(pick.id);
    s.lastEv = s.lastEv.slice(-2);
    return { id: pick.id };
  }

  function cureFull(s) {
    var h = find(s, 'Halfr');
    if (h && !h.dead) h.hp = 2;
    s.sick.stage = 0; s.sick.resolved = true;
  }
  function setStage(s, st) {
    s.sick.stage = st; s.sick.resolved = false; s.sick.next = s.day + 2;
    var h = find(s, 'Halfr');
    if (h && !h.dead && h.hp > 1) h.hp = 1;
  }
  function graveHalfr(s) {
    var h = find(s, 'Halfr');
    if (h && !h.dead) { h.hp = 0; h.graveF = 2; }
    s.sick.stage = 3; s.sick.resolved = false;
  }

  function upkeep(s) {
    var mouths = 1 + aliveCrew(s) + (s.leg >= 2 ? s.captives : 0);  // skipper + living hands + any captives aboard (each eats one ration a day)
    if (s.food >= mouths) { s.food -= mouths; }
    else {
      // nothing left in the pot. The crew eats first; captives aboard go hungry and the crew hears them
      s.food = Math.max(0, s.food - (1 + aliveCrew(s)));
      if (s.leg >= 2 && s.captives > 0) s.morale = Math.max(0, s.morale - 1);
      s.crew.forEach(function (c) {
        if (!c.dead && c.hp > 0) { c.hp -= 1; if (c.hp === 0) c.graveF = 2; }
      });
      s.morale = Math.max(0, s.morale - 1);
    }
    s.crew.forEach(function (c) {
      if (c.dead) return;
      if (c.hp === 0) { c.graveF -= 1; if (c.graveF < 0) c.dead = true; }
      else c.graveF = 2;
    });
    s.day += 1;
  }

  function endOfDay(s) {
    upkeep(s);
    if (s.hull <= 0) { s.phase = 'end'; s.result = ending(s, 'sunk'); return; }
    var allDead = s.crew.every(function (c) { return c.dead; });
    if (allDead) { s.phase = 'end'; s.result = ending(s, 'crewlost'); return; }
    if (s.leg <= 2 && s.day > WINTER) { s.phase = 'end'; s.result = ending(s, 'frozen'); return; }
    if (s.leg === 3 && s.day > 150) { s.phase = 'end'; s.result = ending(s, 'seaclose'); return; }
    if (s.progress >= 100) {
      if (s.leg === 3) { arrive3(s); return; }
      s.phase = 'end';
      s.result = (s.leg === 2) ? ending2(s) : ending(s, 'arrived');
      return;
    }
    if (s.leg <= 2 && s.progress >= VILLAGE_P && !s.flags.village) { s.phase = 'market'; s.pending = null; return; }   // build round 2 fix: the waystation stop belongs to the crossing legs only, never the southern water-road
    s.pending = drawMorning(s);
    s.phase = 'day';
  }

  function applyChoice(s, i) {
    var id = s.pending.id;
    switch (id) {
      case 'storm':
        if (i === 0) adj(s, { hull: -12, progress: 7, morale: -1 });
        else if (i === 1) adj(s, { hull: -2, progress: 3, morale: -1 });
        else { if (rand(s) < 0.5) adj(s, { progress: 13, morale: 1 }); else adj(s, { hull: -25, wet: 1 }); }
        break;
      case 'w1':
        if (i === 0) { adj(s, { progress: 5 }); cureFull(s); }
        else if (i === 1) {
          adj(s, { food: -3 });
          if (rand(s) < 0.5) cureFull(s); else setStage(s, 2);
        } else { adj(s, { progress: 8 }); setStage(s, 2); }
        break;
      case 'w2':
        if (i === 0) {
          adj(s, { progress: 4 });
          if (rand(s) < 0.5) { s.sick.stage = 1; s.sick.resolved = true; }
          else graveHalfr(s);
        } else { adj(s, { progress: 8 }); graveHalfr(s); }
        break;
      case 'calm':
        if (i === 0) adj(s, { progress: 7, morale: -1 }); else adj(s, { progress: 3 });
        break;
      case 'fog':
        if (i === 0) adj(s, { progress: 3 });
        else { if (rand(s) < 0.6) adj(s, { progress: 11 }); else adj(s, { hull: -12 }); }
        break;
      case 'seals':
        if (i === 0) adj(s, { progress: 3, food: 17 }); else adj(s, { progress: 9 });
        break;
      case 'chud':
        if (i === 0) adj(s, { silver: -1, food: 17, progress: 7 }); else adj(s, { progress: 8 });
        break;
      case 'seam':
        if (i === 0) adj(s, { hull: 8, progress: 3 }); else adj(s, { hull: -10, progress: 8 });
        break;
      case 'rain': adj(s, { progress: 6, morale: -1 }); break;
      case 'aurora': adj(s, { progress: 8, morale: 1 }); break;
      case 'fair': adj(s, { progress: 10 }); break;
      case 'squall':
        if (i === 0) adj(s, { hull: -8, progress: 7 }); else adj(s, { progress: 3, morale: -1 });
        break;
      case 'lowwater':
        if (i === 0) adj(s, { progress: 6 });   // wait for the channel to deepen
        else if (i === 1) {
          if (rand(s) < 0.55) adj(s, { hull: -12, progress: 14 });   // drag her over the bar
          else adj(s, { hull: -22, progress: 14, wet: 1 });
        }
        break;
      case 'portage':
        if (i === 0) adj(s, { progress: 9, morale: -1 });  // warp her through with lines from the bank
        else if (i === 1) {                                // run the rapids under oar
          if (rand(s) < 0.5) { if (s.furs > 0) s.furs -= 1; adj(s, { hull: -18, progress: 18, wet: 1 }); }
          else adj(s, { hull: -8, progress: 18 });
        } else {                                           // unship the cargo and walk it round
          adj(s, { progress: 6 });
          if (s.captives > 0 && rand(s) < 0.35) s.captives -= 1;   // a captive walked is a risk that bolts for the woods
        }
        break;
      case 'nets':
        if (i === 0) adj(s, { progress: 4, food: 10, morale: 1 });   // out with the nets: fresh food, a slow morning
        else adj(s, { progress: 9 });                                 // trust to the pole and push on
        break;
      case 'hearth':
        if (i === 0) adj(s, { morale: 1, progress: 3 });              // songs till late by the fire
        else adj(s, { progress: 8 });                                 // turn in early, gone with the light
        break;
      // build round 2: the southern decks — the Lovat/portage subleg and the Dnieper subleg
      case 'lovat':   // the Lovat shallows: the soft gate near Holmgard, thin-flood mechanics reskinned
        if (i === 0) adj(s, { progress: 6 });
        else {
          if (rand(s) < 0.55) adj(s, { hull: -12, progress: 14 });
          else adj(s, { hull: -22, progress: 14, wet: 1 });
        }
        break;
      case 'portage3':   // the watershed portage: rollers built on site / teamsters hired / a gamble on the keel
        if (i === 0) adj(s, { progress: 6, morale: -1 });
        else if (i === 1) { if (s.silver >= 6) { s.silver -= 6; adj(s, { progress: 12 }); } else adj(s, { progress: 5, morale: -1 }); }
        else {
          if (rand(s) < 0.5) adj(s, { hull: -10, progress: 10 });
          else adj(s, { hull: -18, progress: 10, wet: 1 });
        }
        break;
      case 'ilmenstorm':   // storm on the Ilmen: numbers as the lake storm, rivers offer no sea room
        if (i === 0) adj(s, { hull: -12, progress: 7, morale: -1 });
        else if (i === 1) adj(s, { hull: -2, progress: 3 });
        else { if (rand(s) < 0.5) adj(s, { progress: 13, morale: 1 }); else adj(s, { hull: -25, wet: 1 }); }
        break;
      case 'hoard':   // the hoard-rumor: a flavor gamble on the bank
        if (i === 0) {
          s.silver = Math.max(0, s.silver - 3);
          if (rand(s) < 0.5) s.silver += 8; else adj(s, { morale: 1 });
          adj(s, { progress: 4 });
        } else adj(s, { progress: 7 });
        break;
      case 'tailwind':   // the Dnieper carries you: a free fast day
        if (i === 0) adj(s, { progress: 12 });
        else adj(s, { progress: 7, morale: 1 });
        break;
      case 'fmarket':   // a tribute-town fish market: fresh food cheap
        if (i === 0) { s.silver = Math.max(0, s.silver - 2); adj(s, { food: 20, morale: 1, progress: 4 }); }
        else adj(s, { progress: 9 });
        break;
      case 'ferry':   // the ferrymen hold the bank and their price stands
        if (i === 0) { s.silver = Math.max(0, s.silver - 2); adj(s, { progress: 9 }); }
        else adj(s, { progress: 5, morale: -1 });
        break;
      case 'kinsman':   // a face from the crossing at the bank fire
        if (i === 0) { s.silver = Math.max(0, s.silver - 1); adj(s, { morale: 1, progress: 7 }); }
        else adj(s, { food: -4, morale: 2, progress: 5 });
        break;
      // build round 3: the rapids road — seven rapids, Nenasytets, Khortytsia, the Pecheneg parley, the delta
      case 'rapids1':   // the first of the seven: three passage modes per the DAI
        if (i === 0) adj(s, { hull: (s.flags.lateFleet ? -14 : -6), progress: 8 });   // warp through with lines; alone, no fleet hands to haul
        else if (i === 1) {
          if (rand(s) < 0.5) adj(s, { progress: 14 });
          else adj(s, { hull: (s.flags.lateFleet ? -26 : -18), progress: 6, wet: 1 });   // run under oar
        } else {
          adj(s, { progress: 5 });   // walk the cargo round
          if (s.captives > 0 && rand(s) < 0.25) s.captives -= 1;
        }
        break;
      case 'nenasytets':   // the great rapid: the signature hazard, the chained walk (his D4)
        if (i === 0) {   // walk everything the six miles, drag the hull light through
          adj(s, { progress: 4, morale: -1 });
          if (s.captives > 0 && rand(s) < 0.35) s.captives -= 1;
        } else if (i === 1) {   // drag the empty boat through with volunteers on the line
          if (rand(s) < 0.45) adj(s, { progress: 12 });
          else adj(s, { hull: (s.flags.lateFleet ? -30 : -22), progress: 6, wet: 1 });
        } else {   // run it loaded — a fool's saving
          if (rand(s) < 0.25) adj(s, { progress: 15, morale: 2 });
          else adj(s, { hull: -35, wet: 1, morale: -2 });
        }
        break;
      case 'khortytsia':   // the great island: the cock sacrifice, a morale omen
        if (i === 0) adj(s, { morale: 2, progress: 3 });   // keep the old rites — the lot comes up good
        else { if (rand(s) < 0.5) adj(s, { morale: 1, progress: 6 }); else adj(s, { morale: -2, progress: 6 }); }   // press on without them
        break;
      case 'parley':   // the Pecheneg come to the bank: per the round-37 lock — a fumbled parley is lethal, never a war
        if (i === 0) { s.silver = Math.max(0, s.silver - 5); adj(s, { food: 25, morale: 1, progress: 5 }); }   // horned cattle
        else if (i === 1) { adj(s, { silver: 5, progress: 5 }); }   // ironwork sells well here
        else {   // give offense: peace holds, but the steppe keeps its own law
          if (rand(s) < 0.45) {
            var alive3p = s.crew.filter(function (c) { return !c.dead; });
            if (alive3p.length > 1) { var victim3 = alive3p[Math.floor(rand(s) * alive3p.length)]; victim3.hp = 0; victim3.graveF = 0; }   // an arrow from the bank: he will not see the evening
            adj(s, { morale: -2 });
          } else adj(s, { morale: -2, progress: 7 });
        }
        break;
      case 'delta':   // the reed islands and channels before the bluffs
        if (i === 0) { if (rand(s) < 0.5) adj(s, { progress: 14 }); else adj(s, { hull: -12, progress: 6 }); }
        else adj(s, { progress: 5 });
        break;
      // build round 4: the Greek sea run
      case 'summons':   // the St Mamas wait: the empire's paper decides who sails
        if (i === 0) { s.silver = Math.max(0, s.silver - 3); adj(s, { progress: 8 }); }   // grease the clerk's hand
        else adj(s, { progress: 3 });                                                                                     // wait your turn before the white bluffs
        break;
      case 'escort':   // the imperial dromons, per the treaty
        if (i === 0) adj(s, { progress: 10, morale: 1 });                                  // fall in with the escort
        else adj(s, { progress: 13 });                                                                                     // sail apart, faster and alone
        break;
      case 'cstorm':   // the Black Sea storm
        if (i === 0) adj(s, { hull: -10, progress: 8 });
        else if (i === 1) { s.silver = Math.max(0, s.silver - 4); adj(s, { progress: 5 }); }   // put in at a fisher haven
        else { if (rand(s) < 0.5) adj(s, { progress: 15, morale: 1 }); else adj(s, { hull: -25, wet: 1, morale: -2 }); }
        break;
      case 'mesembria':   // the Mesembria landfall: tar, water, the last cheap bread
        if (i === 0) { s.silver = Math.max(0, s.silver - 2); adj(s, { food: 15, hull: 10, progress: 3 }); }
        else adj(s, { progress: 11 });
        break;
      case 'statherios':   // St Aitherios: the last re-rig on the imperial road
        if (i === 0) adj(s, { hull: 12, progress: 4 });
        else adj(s, { progress: 9, morale: 1 });
        break;
    }
    endOfDay(s);
  }

  // crew replacement is a POST-SETTLEMENT activity (v0.2 hub phase: hire with the marks from selling the cargo),
  // not mid-leg petty-cash hiring. Banked for the second leg; the hire pool is on file:
  // var HIRES = ['Audun', 'Thorstein', 'Ragnvald', 'Sverting'];

  function marketAct(s, a) {
    if (s.phase !== 'market') return;
    if (a === 'fish' && s.silver >= 2) { s.silver -= 2; s.food += 30; }
    else if (a === 'careen' && s.silver >= 4) { s.silver -= 4; s.hull = Math.min(100, s.hull + 25); }
    else if (a === 'wise' && s.silver >= 2) {
      s.silver -= 2;
      s.crew.forEach(function (c) { if (!c.dead && c.hp < 2) { c.hp += 1; c.graveF = 2; } });
      var h = find(s, 'Halfr');
      if (h && !h.dead && h.hp >= 1) { s.sick.stage = 1; s.sick.resolved = true; }
    }
    else if (a === 'rest' && !s.flags.rested) {
      s.flags.rested = true;
      s.morale = Math.min(10, s.morale + 1);
      s.crew.forEach(function (c) { if (!c.dead && c.hp === 0) c.graveF = 2; });
      upkeep(s);
      if (s.day > WINTER) { s.phase = 'end'; s.result = ending(s, 'frozen'); }
    }
    else if (a === 'castoff') {
      s.flags.village = true;
      s.pending = drawMorning(s);
      s.phase = 'day';
    }
  }

  // v0.2 hub: the landing at Aldeigjuborg between the legs. Crew replacement is paid from the earned
  // settlement purse (with the buyer's silver, not petty cash), alongside buying the upriver cargo.
  function holdUsed(s) { return s.furs + s.captives * 2 + (s.freight || 0) + (s.greek || 0); }

  function enterHub(s) {
    s.silver += (s.result && s.result.marks) || 0;   // the settlement lands in the purse
    s.scoreSaved = false;   // the river venture is a new run on the skippers' board
    s.phase = 'hub';
  }

  function hubAct(s, a) {
    if (s.phase !== 'hub') return;
    if (a === 'hire' && s.silver >= 5) {
      var free = HIRES.filter(function (n) {
        return !s.crew.some(function (c) { return c.name === n || c.dead === false && c.name === n; });
      });
      var taken = s.crew.map(function (c) { return c.name; });
      var name = HIRES.filter(function (n) { return taken.indexOf(n) < 0; })[0];
      if (name) { s.silver -= 5; s.crew.push({ name: name, role: 'oarsman', hp: 2, dead: false, graveF: 2 }); }
    }
    else if (a === 'furs' && s.silver >= 2 && holdUsed(s) + 1 <= HOLD) { s.silver -= 2; s.furs += 1; }
    else if (a === 'captive' && s.silver >= 4 && holdUsed(s) + 2 <= HOLD) { s.silver -= 4; s.captives += 1; }
    else if (a === 'freight' && holdUsed(s) + 1 <= HOLD) { s.freight = (s.freight || 0) + 1; }  // a merchant's bale carried south — 2 dirhams per unit paid at Holmgard
    else if (a === 'fish' && s.silver >= 2) { s.silver -= 2; s.food += 30; }
    else if (a === 'careen' && s.silver >= 4) { s.silver -= 4; s.hull = Math.min(100, s.hull + 25); }
    else if (a === 'wise' && s.silver >= 2) {
      s.silver -= 2;
      s.crew.forEach(function (c) { if (!c.dead && c.hp < 2) { c.hp += 1; c.graveF = 2; } });
      var h = find(s, 'Halfr');
      if (h && !h.dead && h.hp >= 1) { s.sick.stage = 1; s.sick.resolved = true; }
    }
    else if (a === 'rest' && !s.flags.rested) {
      s.flags.rested = true;
      s.morale = Math.min(10, s.morale + 1);
      s.crew.forEach(function (c) { if (!c.dead && c.hp === 0) c.graveF = 2; });
      upkeep(s);
      if (s.day > WINTER) { s.phase = 'end'; s.result = ending(s, 'frozen'); }
    }
    else if (a === 'feast' && s.silver >= 2 && !s.flags.feasted) {
      s.silver -= 2;
      s.morale = Math.min(10, s.morale + 2);
      s.flags.feasted = true;   // one feast at the landing — mead and meat while the purse holds
    }
    else if (a === 'castoff2') {
      s.leg = 2;
      s.progress = 0;
      s.flags.rested = false;   // a fresh rest is possible upriver
      s.flags.feasted = false;  // and a fresh feast at any later landing
      s.lastEv = [];
      s.pending = drawMorning(s);
      s.phase = 'day';
    }
  }

  // ===================== LEG THREE: the road to Miklagard (round 38, build round 1) =====================
  // five hubs per the signed brief; s.sub = the subleg about to be sailed (Holmgard->Gnezdovo->Kiev->Cherson->Miklagard)
  var HUB3N = ['holmgard', 'gnezdovo', 'kiev', 'cherson'];   // HUB3N[s.sub-1] = the hub you cast off FROM
  function leg3Dest(sub) { return ['Gnezdovo', 'Kiev', 'Cherson', 'Miklagard'][(sub || 1) - 1]; }

  function begin3(s) {
    s.greek = 0;   // round 51: bales of Greek goods bought at the Cherson market, paid out at Miklagard
    s.leg = 3; s.sub = 1; s.hub = 'holmgard'; s.progress = 0;
    s.lastEv = []; s.pending = null;
    s.flags.rested = false; s.flags.feasted = false;
    s.flags.lateFleet = false; s.flags.freightPaid = 0;
    s.scoreSaved = false;   // leg three is one scoring run, anchoring at Miklagard
    s.morale = Math.min(10, s.morale + 1); s.flags.hubLift = 1;   // round 42: the landing lifts the crew, arrival bonus at every hub
    s.phase = 'hub3';
  }

  function hub3Act(s, a) {
    if (s.phase !== 'hub3') return;
    if (a === 'fish' && s.silver >= 2) { s.silver -= 2; s.food += 30; }
    else if (a === 'caulk' && s.silver >= 4) { s.silver -= 4; s.hull = Math.min(100, s.hull + 25); }
    else if (a === 'hire' && s.silver >= 5) {
      var taken3 = s.crew.map(function (c) { return c.name; });
      var nm3 = HIRES.filter(function (n) { return taken3.indexOf(n) < 0; })[0];
      if (nm3) { s.silver -= 5; s.crew.push({ name: nm3, role: 'oarsman', hp: 2, dead: false, graveF: 2 }); }
    }
    else if (a === 'freight' && (s.hub === 'holmgard' || s.hub === 'gnezdovo') && holdUsed(s) + 1 <= HOLD) { s.freight = (s.freight || 0) + 1; }  // freight taken south pays at Kiev
    else if (a === 'buyfur' && s.hub === 'holmgard' && s.silver >= 2 && holdUsed(s) + 1 <= HOLD) { s.silver -= 2; s.furs += 1; s.flags.hmgFur = (s.flags.hmgFur || 0) + 1; }   // round 53: goods bought here are marked - the factor never buys them back (his exploit fix)   // round 42: Holmgard trade — buy the southern venture's cargo
    else if (a === 'buycap' && s.hub === 'holmgard' && s.silver >= 4 && holdUsed(s) + 2 <= HOLD) { s.silver -= 4; s.captives += 1; s.flags.hmgCap = (s.flags.hmgCap || 0) + 1; }
    else if (a === 'sellfur' && s.hub === 'holmgard' && (s.furs - (s.flags.hmgFur || 0)) > 0) { var ff = s.furs - (s.flags.hmgFur || 0); s.silver += ff * 3; s.furs -= ff; }   // round 53: only furs NOT bought at Holmgard (his exploit fix)
    else if (a === 'buygreek' && s.hub === 'cherson' && s.silver >= 3 && holdUsed(s) + 1 <= HOLD) { s.silver -= 3; s.greek = (s.greek || 0) + 1; }   // round 51: the Greek market — hold space is the cap, the factor pays 6 a bale at Miklagard   // the factor's quick price: 3 a bale — a fallback, not the play
    else if (a === 'buybread' && s.hub === 'gnezdovo' && s.silver >= 2) { s.silver -= 2; s.food += 20; }   // round 53: the Gnezdovo market — bread and dried fish for the rapids road
    else if (a === 'gsellfur' && s.hub === 'gnezdovo' && s.furs > 0) { s.silver += s.furs * 2; s.furs = 0; }   // the smola factor pays the winter price — nothing here sells above its buy, no loop
    else if (a === 'gsellcap' && s.hub === 'gnezdovo' && s.captives > 0) { s.silver += s.captives * 4; s.captives = 0; }
    else if (a === 'kbread' && s.hub === 'kiev' && s.silver >= 2) { s.silver -= 2; s.food += 25; s.morale = Math.min(10, s.morale + 1); }   // round 55: the Kiev market — fresh bread and grain from the hinterland, the gathering's plenty lifts spirits
    else if (a === 'ksellfur' && s.hub === 'kiev' && s.furs > 0) { s.silver += s.furs * 3; s.furs = 0; }   // round 55: the fleet merchants pay above the waystation's price — nothing can be BOUGHT here, so no loop; the rapids road may still take what they carry
    else if (a === 'ksellcap' && s.hub === 'kiev' && s.captives > 0) { s.silver += s.captives * 5; s.captives = 0; }
    else if (a === 'sellcap' && s.hub === 'holmgard' && (s.captives - (s.flags.hmgCap || 0)) > 0) { var cc = s.captives - (s.flags.hmgCap || 0); s.silver += cc * 6; s.captives -= cc; }
    else if (a === 'rest' && !s.flags.rested) {
      s.flags.rested = true;
      s.morale = Math.min(10, s.morale + 1);
      s.crew.forEach(function (c) { if (!c.dead && c.hp === 0) c.graveF = 2; });
      upkeep(s);
      if (s.day > 150) { s.phase = 'end'; s.result = ending(s, 'seaclose'); }
    }
    else if (a === 'feast' && s.silver >= 2 && !s.flags.feasted) {
      s.silver -= 2;
      s.morale = Math.min(10, s.morale + 2);
      s.flags.feasted = true;
    }
    else if (a === 'castoff3') {
      s.progress = 0;
      s.flags.rested = false;
      s.flags.feasted = false;
      s.flags.hubLift = false;
      s.flags.l3Lovat = false;   // build round 2: the Lovat/portage gates belong to subleg 1 only
      s.flags.l3Port = false;
      s.flags.l3Rap = false; s.flags.l3Nen = false; s.flags.l3Khor = false;   // build round 3: the rapids-road gates
      s.flags.l3Delta = false; s.flags.l3Parley = false;
      s.flags.l3Summ = false; s.flags.l3Esc = false; s.flags.l3Mes = false; s.flags.l3Aith = false;   // build round 4: the sea gates
      s.lastEv = [];
      s.pending = drawMorning(s);
      s.phase = 'day';
    }
  }

  function arrive3(s) {
    var done = s.sub;
    if (done === 2) {   // Kiev: freight contracts pay out here, and the June fleet is the gate
      if (s.freight) { s.silver += s.freight * 2; s.flags.freightPaid = s.freight; s.freight = 0; }
      if (s.day > FLEET) s.flags.lateFleet = true;
    }
    if (done === 3 && s.day > SEACLOSE) {   // Cherson: the summons stops coming
      s.phase = 'end'; s.result = ending(s, 'seaclose'); return;
    }
    if (done === 4) { s.phase = 'end'; s.result = ending3(s); return; }   // Miklagard: the finale is the last leg's score (his D5)
    s.sub = done + 1;
    s.hub = HUB3N[s.sub - 1];
    s.morale = Math.min(10, s.morale + 1); s.flags.hubLift = 1;   // round 42: arrival lifts spirits at every hub, capped at 10
    s.pending = null;
    s.phase = 'hub3';
  }

  function ending(s, how) {
    var alive = s.crew.filter(function (c) { return !c.dead; });
    var deaths = s.crew.length - alive.length;
    var base = {
      how: how, dest: (s.leg === 3 ? leg3Dest(s.sub) : 'Aldeigjuborg'), date: dateStr(s.day), days: s.day,
      crew: s.crew.map(function (c) { return { name: c.name, dead: !!c.dead }; }),
      deaths: deaths, wet: s.wet, silver: s.silver, morale: s.morale
    };
    if (how === 'sunk') {
      base.tier = 'fail'; base.title = 'The sea keeps the ledger'; base.marks = 0;
      base.text = 'The storm opens the old seams and the lake light goes green through the hold. Some of yours swim. The cargo does not.';
    } else if (how === 'crewlost') {
      base.tier = 'fail'; base.title = 'A ship of ghosts'; base.marks = 0;
      base.text = 'You bring the knarr in alone, paying the last watches with silence. The ledger pays the cargo and takes blood in the same line.';
    } else if (how === 'frozen') {
      base.tier = 'fail'; base.title = 'The season slips away'; base.marks = 0;
      base.text = (s.leg === 2)
        ? 'The weeks slid past on the river and the southbound convoys sailed from the landing without you. The furs sit unsold while the season turns.'
        : 'The last southbound convoys are hulls on the horizon, and the weighing-house stands empty. The summer will pass without you in it.';
    } else if (how === 'seaclose') {
      base.tier = 'seafail'; base.title = 'The sea closes'; base.marks = 0;
      base.text = 'The last summons sails from Cherson without you, and the first gales walk the open water. The road south is barred for this year — the furs will have to sit in a stranger\u2019s shed while the season turns.';
    } else {
      var late = s.day > FREEZE;
      var marks = Math.max(0, 30 - deaths * 10 - s.wet * 5);
      if (late) marks = Math.floor(Math.max(0, marks) / 2);
      if (late && s.day > 41) {
        base.tier = 'winterover'; base.title = 'The landing has emptied'; base.marks = 0;
        base.text = 'Leif sailed south with the last of the convoys. You sell a bale at a loss to the first Chud with a dry shed, and watch the river go quiet for the summer.';
      } else if (late) {
        base.tier = 'ice'; base.title = 'The convoys are gone'; base.marks = marks;
        base.text = 'Leif\u2019s factor pays half against the season, eyes on the emptying landing. The bargain held; the calendar did not.';
      } else if (deaths === 0 && s.wet === 0) {
        base.tier = 'full'; base.title = 'Full settlement'; base.marks = 38;
        base.text = 'Leif\u2019s man counts the bales by lamplight: all dry, all hands standing. Eight dirhams added for beating the season. The silver is heavy and honestly come by.';
      } else {
        base.tier = 'scales'; base.title = 'Weighted scales'; base.marks = marks;
        base.text = 'The bargain holds, but Leif counts what is missing, and prices it. The scales settle; nobody calls it even.';
      }
    }
    return base;
  }

  // v0.2: the second leg's settlement at Holmgard — furs and captives are the venture's cargo
  function ending2(s) {
    var alive = s.crew.filter(function (c) { return !c.dead; });
    var deaths = s.crew.length - alive.length;
    var base = {
      how: 'arrived', dest: 'Holmgard', date: dateStr(s.day), days: s.day,
      crew: s.crew.map(function (c) { return { name: c.name, dead: !!c.dead }; }),
      deaths: deaths, wet: s.wet, silver: s.silver, morale: s.morale,
      marks: s.furs * 5 + s.captives * 12 + (s.freight || 0) * 2
    };
    if (s.freight) base.textExtra = ' The merchants\u2019 ' + s.freight + ' bale' + (s.freight === 1 ? ' passes' : 's pass') + ' from your hold to the jetty scale — ' + (s.freight * 2) + ' dirham' + (s.freight * 2 === 1 ? '' : 's') + ' of freight silver, counted on the spot.';
    if (deaths === 0 && s.wet === 0 && s.captives === 0) {
      base.tier = 'full2'; base.title = 'The gorod takes it all';
      base.text = 'Sable and squirrel change hands by weight at the wharf, the dirhams run into your purse like water, and the town criers call the water-roads open. No man missing, no bale wet, nothing in the hold that walks.';
    } else {
      base.tier = 'holmgard'; base.title = 'Holmgard at last';
      base.text = 'The boat grounds below the wharves and the haggle begins before the ropes are fast. Furs by weight, the rest by head-count; every loss is counted twice — once here, once on the river.';
    }
    if (base.textExtra) base.text += base.textExtra;
    return base;
  }

  // v0.3 build round 1: the finale settlement at Miklagard — the venture scores like every other leg (his D5: no silk beat, just the score)
  function ending3(s) {
    var alive3 = s.crew.filter(function (c) { return !c.dead; });
    var deaths3 = s.crew.length - alive3.length;
    var base = {
      how: 'arrived', dest: 'Miklagard', date: dateStr(s.day), days: s.day,
      crew: s.crew.map(function (c) { return { name: c.name, dead: !!c.dead }; }),
      deaths: deaths3, wet: s.wet, silver: s.silver, morale: s.morale,
      marks: s.furs * 5 + s.captives * 12
    };
    if (deaths3 === 0 && s.wet === 0 && !s.flags.lateFleet) {
      base.tier = 'full3'; base.title = 'The Golden Horn takes it all';
      base.text = 'Under the walls of Miklagard the emperor\u2019s men count the venture out — furs by weight, the rest by head — before a crowd of ten nations, the city\u2019s bricked mass standing over the water like a cliff. No man missing, no bale wet, and the fleet\u2019s own hulls behind you.';
    } else {
      base.tier = 'miklagard'; base.title = 'Miklagard at last';
      base.text = 'The knarr comes up the Horn with the tide and ties among a hundred hulls. The scales wait on the jetty; every loss of the road is counted twice — once here, once on the water behind you.';
      if (s.flags.lateFleet) base.text += ' You came south behind the June fleet, and the payslips notice.';
    }
    if (s.flags.freightPaid) base.text += ' The merchants\u2019 ' + s.flags.freightPaid + ' freight bale' + (s.flags.freightPaid === 1 ? '' : 's') + ' settled at Kiev — ' + (s.flags.freightPaid * 2) + ' dirham' + (s.flags.freightPaid * 2 === 1 ? '' : 's') + ' to the purse.';
    if (s.greek) { s.silver += s.greek * 6; base.silver = s.silver; base.text += ' A factor of the Greek houses takes the ' + s.greek + ' bale' + (s.greek === 1 ? '' : 's') + ' of Cherson goods over the jetty — six dirhams apiece, ' + (s.greek * 6) + ' to the purse.'; s.greek = 0; }   // round 51: the Greek market pays out at the Horn
    return base;
  }

  var TEXTS = {
    storm: { title: 'The sky goes green-black', text: 'The storm stands off the skerries like a wall. Ketil looks at the clouds, then at you.', opts: ['Race ahead of it with a small sail (fast, but the ship takes damage)', 'Stop and let it pass (safe, but a whole day lost)', 'Sail between the rocks to slip past it (huge speed, or disaster)'] },
    calm: { title: 'Dead calm', text: 'The tar sweats in the seams. The crew sits at the oars and waits on your word.', opts: ['Row all day (good speed, the crew suffers)', 'Rest and wait for wind (slow and easy)'] },
    fog: { title: 'A grey wall of fog', text: 'The lead-line knocks against the rail like a slow clock.', opts: ['Stop and wait for it to lift (safe, a lost morning)', 'Sail on blind, feeling for rocks with the line (fast, the ship may strike a rock)'] },
    seals: { title: 'Seals on the skerry', text: 'Seals bask on a low rock. Ottar strings his bow without being asked.', opts: ['Let him hunt — fresh meat for the pots (slow day, +food)', 'Press on with the sailing (good speed)'] },
    chud: { title: 'A Chud log-boat', text: 'It shadows you at half a mile: two men, laden with smoked fish, paddling sideways to show their goods.', opts: ['Buy smoked fish — one dirham (+much food)', 'Wave them off and keep going (good speed)'] },
    seam: { title: 'The newest seam is leaking', text: 'Groa has the tar pot warm before you finish the sentence. It is your call.', opts: ['Stop and seal it properly (slow, the ship heals)', 'Patch it while sailing (fast, the leak will worsen)'] },
    rain: { title: 'Cold rain, straight down', text: 'Hoods up, backs bowed. The Baltic does not care whose crossing this is.', opts: ['Endure it'] },
    aurora: { title: 'The sky burns green', text: 'That night the northern sky drips silver fire. No one speaks of it. In the morning the oars seem lighter.', opts: ['Take it as a good omen'] },
    fair: { title: 'A fair wind off the quarter', text: 'The knarr leans her shoulder in and runs. Even the bailers get to rest.', opts: ['Let her run'] },
    w1: { title: 'Halfr shivers by the mast', text: 'His teeth rattle like loose rigging. Groa presses a hand to his brow, then shakes her head at you.', opts: ['Rest the whole crew a day so he can sweat it out (slow, but he should recover)', 'Broth and careful nursing tonight (costs food, he may still worsen)', 'Make him row (good speed, he will surely worsen)'] },
    w2: { title: 'Halfr cannot close his hands', text: 'He will not say where it hurts. He will not let go of the oar, either.', opts: ['Take a slow, gentle day — lay him in the stern (slow, half a chance he turns)', 'Keep the pace — the oars need backs (good speed, he will not last)'] },
    squall: { title: 'A black squall off the Ladoga shore', text: 'A wall of weather stands between you and the river mouth. Run its edge, or let it pass.', opts: ['Race along its edge (fast, the ship takes damage)', 'Hold still and let it pass (safe, a lost day)'] },
    lowwater: { title: 'The river runs thin', text: 'Sandbars stand yellow where last week the channel ran two fathoms. The pole confirms it: the river is near her bones already — this year even the spring flood ran thin — the old hands nod it through.', opts: ['Lay at anchor and wait for the water to deepen (safe, a slow morning)', 'Drag her over the bar with the crew in the shallows (fast, the hull may open on the sand)'] },
    portage: { title: 'The bypass rapids', text: 'The river throws itself white over the Gostinopol rift — the rapids that stand guard at Holmgard\u2019s door. Even the locals lose keels here; the old way round is goods walked along the bank and the boat warped up on lines.', opts: ['Warp her through the rift with lines from the bank (everyone hauls, the crew suffers)', 'Run the rapids under oar (very fast, the hull may open and a bale may soak)', 'Unship the cargo and walk it round the path (a whole safe day — but a walked captive may bolt for the woods)'] },
    nets: { title: 'The quiet water below the rift', text: 'Below the last white water the current slows and shoals, pike basking in the shallows where the river spreads wide. A night of nets here would fill the fish-boxes — but every hour at anchor is an hour lost upriver.', opts: ['Out with the nets (fresh food, a slow morning)', 'Trust to the pole and push on (good speed)'] },
    hearth: { title: 'A night camp on the shingle', text: 'A dry bar of stones above the current, birchwood at hand. The hands look at the fire-pit and then at the pole — a night of songs would lift hearts gone thin on smoked fish, and cost the morning light.', opts: ['Sit the night by the fire — songs till late (spirits rise, a slow start)', 'Turn in early and be gone with the light (good speed)'] },
    // build round 2: the southern water-road decks (per the signed brief)
    lovat: { title: 'The Lovat runs shallow', text: 'South of the town the river narrows to her early-summer bones — gravel bars standing yellow midstream, bargemen poling the shallows with their cargo on their backs. On the Dnieper side the water-road runs deep all the way to the Greek sea; on this side, the heights pay for the crossing.', opts: ['Wait out the morning for the channel to ease (safe, a slow watch)', 'Warp her over the bars with lines and shoulders (fast, the hull may open)'] },
    portage3: { title: 'The watershed portage', text: 'Between the Lovat\u2019s headwaters and the Dnieper side the boats go overland — a stage of dry ground where the rivers forget each other. Slavic teamsters wait by the track with their wheels, asking honest money; the other road is rollers cut on site and the whole crew\u2019s backs.', opts: ['Build rollers on site and sweat her over (free, hard days)', 'Hire the teamsters with their wheels (6 dirhams, over by dusk)', 'Grease skids and gamble the keel on the first riffle (fast, the hull may open)'] },
    ilmenstorm: { title: 'Storm on the Ilmen', text: 'The lake the Rus call the Great One stands up grey and white-maned under the leading of the wind — a short crossing, but open water all the same, and the knarr is loaded deep with the southern venture.', opts: ['Haul on and take it (the ship suffers, the day is kept)', 'Run for the reeds and wait it out (safe, a lost morning)', 'Race the storm\u2019s tail across (fast if you win the race)'] },
    hoard: { title: 'A hoard-rumor at the landing', text: 'At the net-menders\u2019 fire a digger claims a cracked pot of dirhams under an old barrow, a morning\u2019s walk from here. He will sell the third of it for three dirhams and his silence. The old hands laugh. The old hands also look at the barrow.', opts: ['Buy the digger\u2019s share of the rumor (3 dirhams — a trifle or a bargain)', 'Count news worth more than silver and press on (good speed)'] },
    tailwind: { title: 'The current does the rowing', text: 'The Dnieper takes the knarr on her shoulder like a mother with a child — broad brown water, wind over the quarter, the pools and reedbanks sliding past faster than any keel-man could ask.', opts: ['Ride the broad reach with watches shortened (very fast)', 'Keep the crew honest at the oars anyway (a steady watch, good spirits)'] },
    fmarket: { title: 'A tribute-town on the bank', text: 'A stockaded town above the fish-stages, smoke and scales on the wind — the Krivich render their dusk here, and the fish-market is loud with it. Fresh-caught, cheap, and the men can smell it from the water.', opts: ['Buy the morning\u2019s catch (2 dirhams, fresh food, spirits rise)', 'Hold off the stages and push on (good speed)'] },
    ferry: { title: 'The ferrymen\u2019s crossing', text: 'The broad channel bends at a bluff, and the ferrymen hold it — big dugouts, tarred and quiet, and a price that is not negotiable. Upstream everyone pays it; there is no other channel.', opts: ['Pay the crossing (2 dirhams, through by mid-day)', 'Stand off and look for your own way over (a lost morning, spirits dip)'] },
    kinsman: { title: 'A kinsman from the crossing', text: 'By a bank fire a face you know lifts from the pot — a Chud spearman from the lake country, gone south with the fur-roads like half the world. He has news of the river ahead, and news wants paying for.', opts: ['Trade a dirham and gifts for his news (spirits rise, good speed)', 'Berth him aboard a night and share the porridge (costs food, the crew sings)'] },
    // build round 3: the rapids road (per the signed brief and the round-37 locks)
    rapids1: { title: 'The first of the seven', text: 'The Dnieper gathers herself white over a spine of grey stone \u2014 the first rapid of the road. The old Rus names have no gentleness in them for any of the seven. Boats warp through on lines from the rocks, run the tongue under oar, or the cargo goes round on the bank path.', opts: ['Warp her through with lines from the rocks (the hull scrapes)', 'Run the tongue under oar (fast, a gamble on the stone)', 'Unship the cargo and walk it round (a whole safe day \u2014 a walked captive may bolt)'] },
    nenasytets: { title: 'Nenasytets, the insatiable', text: 'The great rapid \u2014 \'The one that cannot be sated.\' The whole river falls through a throat of stone, and no loaded keel lives in it. The Rus walk everything six miles by the portage path, captives on the chain-line ahead, and drag the empty hull through with volunteers on the rope. Chained men walk slowly. Unchained men sometimes do not walk the whole way.', opts: ['Walk everything the six miles, drag the hull light (slow, a captive may bolt on the chain-line)', 'Drag the empty boat through with volunteers (the rope may hold)', 'Run it loaded \u2014 no Rus keel dares this (a fool\u2019s saving, the hull may not live)'] },
    khortytsia: { title: 'The great island', text: 'Below the last of the falls the river splits round a great green island, and the Rus yiels call it holy ground. The old rite here: cast the lots, and if they come up good, sacrifice the cock. The crew look at you, then at the cock. There is, as the traders say, only one way to know.', opts: ['Keep the old rites \u2014 a cock for the island (spirits rise)', 'Press on without them (the crows watch you go)'] },
    parley: { title: 'The Pecheneg come to the bank', text: 'Horsemen on the bluff, tall saddles and horn bows, unhurried as weather. This summer they are at peace \u2014 the kind of peace that holds while it is fed. They will trade horned cattle for silver, take good iron at a fair word, or take offense if it is offered. Offense, on this shore, is paid for on the spot.', opts: ['Buy horned cattle (5 dirhams \u2014 meat aboard, the parley holds)', 'Sell ironwork to them (they pay well for good iron)', 'Wave them off from the water (fast \u2014 but a fumbled parley can cost a man where he stands)'] },
    delta: { title: 'The reeds and the channels', text: 'The river forgets her banks and braids across a plain of reed islands \u2014 channels everywhere, none of them promising. The convoy men say the deepest thread runs close under the far sand bluff. The convoy men are not here.', opts: ['Thread the deep channel fast (a gamble on the sand)', 'Take the slow channel with the poles (safe, a lost day)'] },
    // build round 4: the Greek sea run (per the signed brief)
    summons: { title: 'The summons wait', text: 'The white bluffs of St Mamas, and the empire\u2019s patience: no Rus keel clears the water without its summons. The clerks on the jetty hold the seals like weather. There is a queue, and there is a way through a queue.', opts: ['Grease the clerk\u2019s hand (3 dirhams — your seal is cut the same day)', 'Wait your turn honestly before the bluffs (the season burns, the seal comes)'] },
    escort: { title: 'The dromons come out', text: 'Out of the haze, two imperial dromons — high sterns, bronze pipes glittering at the bows. The treaty letter is plain: the Rus sail under the emperor\u2019s eye from Cherson to the Horn, or answer for themselves alone.', opts: ['Fall in with the escort (steady sailing, spirits rise)', 'Sail apart from the convoy (faster — and alone with the sea)'] },
    cstorm: { title: 'A Black Sea storm', text: 'The horizon bruises and the wind comes off the steppe-water like a shoulder. Coasting here you are never far from a lee shore, and never far from deep water either. The hands look at the sky, then at you.', opts: ['Hold out to sea and take it (the ship suffers, the day is kept)', 'Put in at a fisher haven and ride it out (4 dirhams of ground tackle)', 'Run the coast before it (fast — if the timing holds)'] },
    mesembria: { title: 'The Mesembria landfall', text: 'A Greek harbour town under its headland, tile roofs and church bells, fishermen hawking the day\u2019s catch. The last soft water and cheap bread before the capital; the last honest tar, too.', opts: ['Lay over half a day — water, bread, tar and pitch (2 dirhams, hull and larder mend)', 'Stand off and on, straight for the Horn (good speed)'] },
    statherios: { title: 'St Aitherios on the cape', text: 'A staging shrine on the last cape, keels moored two and three deep, riggers splicing for anyone with coin — or without. Past here it is one day\u2019s open water, then the Walls: the Horn and the city beyond counting.', opts: ['Re-rig the spare and patch every seam (the hull answers)', 'Hold course with what you have — the crew can taste the Horn (good speed, spirits rise)'] }
  };

  function currentEvent(s) {
    var t = TEXTS[s.pending.id];
    return { id: s.pending.id, title: t.title, text: t.text, options: t.opts };
  }

  function moraleLabel(m) {
    if (m >= 8) return 'high';
    if (m >= 5) return 'steady';
    if (m >= 3) return 'low';
    return 'near mutiny';
  }

  return {
    newRun: newRun, applyChoice: applyChoice, marketAct: marketAct,
    hubAct: hubAct, enterHub: enterHub, holdUsed: holdUsed, ending2: ending2,
    begin3: begin3, hub3Act: hub3Act, arrive3: arrive3, ending3: ending3, leg3Dest: leg3Dest, drawMorning: drawMorning,
    HUB3N: HUB3N, FLEET: FLEET, SEACLOSE: SEACLOSE,
    currentEvent: currentEvent, dateStr: dateStr, moraleLabel: moraleLabel,
    begin: function (s) { s.pending = drawMorning(s); s.phase = 'day'; },
    begin3: begin3, hub3Act: hub3Act, arrive3: arrive3, ending3: ending3,
    crewFactor: crewFactor, upkeep: upkeep,
    MOUTHS: MOUTHS, FREEZE: FREEZE, WINTER: WINTER, VILLAGE_P: VILLAGE_P,
    HIRES: HIRES, HOLD: HOLD, leg: function (s) { return s.leg; }
  };
})();

/* ---------- storage (localStorage may be unavailable in sandbox previews) ---------- */
var SR = (function () {
  var mem = {};
  var ok = false;
  try { localStorage.setItem('__hmg_t', '1'); localStorage.removeItem('__hmg_t'); ok = true; } catch (e) { ok = false; }
  return {
    get: function (k) {
      try { if (ok) return localStorage.getItem(k); } catch (e) {}
      return Object.prototype.hasOwnProperty.call(mem, k) ? mem[k] : null;
    },
    set: function (k, v) {
      try { if (ok) { localStorage.setItem(k, v); return; } } catch (e) {}
      mem[k] = v;
    },
    del: function (k) {
      try { if (ok) { localStorage.removeItem(k); } } catch (e) {}
      delete mem[k];
    }
  };
})();
var KEY = 'hmg01save', KEYS = 'hmg01seed', KEYB = 'hmg01board';
function runScore(r) {
  var alive = r.crew.filter(function (c) { return !c.dead; }).length;
  var speed = Math.max(0, (HMG.FREEZE - r.days) * 25);
  return { total: r.marks * 100 + alive * 50 + speed + r.silver * 20, alive: alive, speed: speed };
}
function boardGet() {
  try { return JSON.parse(SR.get(KEYB) || '[]'); } catch (e) { return []; }
}
function farArrival() {   // round 53, his ask: no more silent landings - Gnezdovo, Kiev and Cherson score the venture so far onto the far-shore board
  var st = S.sub; S.flags['sc3' + st] = 1;   // this landing is scored; a later render must not score it twice
  if (!S.flags.test) {
    var marks = (S.furs || 0) * 5 + (S.captives || 0) * 12 + (S.greek || 0) * 6 + (S.freight || 0) * 2;   // the venture so far: cargo still afloat at destination terms
    var alive = S.crew.filter(function (c) { return !c.dead; }).length;
    var speed = Math.max(0, (HMG.FREEZE - S.day) * 25);
    var total = marks * 100 + alive * 50 + speed + S.silver * 20;
    var nm = (S.name || SR.get('hmg01name') || 'The skipper').slice(0, 18); S.name = nm;
    var row = { n: nm, s: total, d: S.day, m: marks, t: 'full', g: ['Gnezdovo', 'Kiev', 'Cherson'][st - 2] };   // t: 'full' = made it whole; g: the CHECK-legal capitalized landing
    sbPush(row); sbRank(row);   // offline-safe; test runs never reach here
    S.flags.arrivalScore = row;
    save();
  }
}
function boardSave(name) {
  if (S.flags && S.flags.test) { S.scoreSaved = true; return; }   // test runs never enter the skippers\u2019 board
  var r = S.result, sc = runScore(r);
  var nm = (name || S.name || SR.get('hmg01name') || 'The skipper').slice(0, 18);
  S.name = nm;
  var b = boardGet();
  b.push({ n: nm, s: sc.total, d: r.days, m: r.marks, t: r.tier, g: r.dest || 'Aldeigjuborg' });
  b.sort(function (x, y) { return y.s - x.s; });
  b = b.slice(0, 10);
  SR.set(KEYB, JSON.stringify(b));
  var _row = { n: nm, s: sc.total, d: r.days, m: r.marks, t: r.tier, g: r.dest || 'Aldeigjuborg' };
  sbPush(_row);   // round 49: row it to the far-shore board too (offline-safe)
  sbRank(_row);   // round 50: and fetch where this venture stands at that landing
  S.scoreSaved = true;
  save();
  keepScroll = true;  // don't yank the view to the top when the score lands
  render();
}
function boardHtml(limit) {
  var b = boardGet();
  if (!b.length) return '';
  var rows = b.slice(0, limit).map(function (e, i) {
    return '<div class="row"><span>' + (i + 1) + '. ' + e.n + '</span><span>' + e.s + ' <span class="mut">— ' + (e.g || 'Aldeigjuborg') + ', day ' + e.d + ', ' + e.m + ' dirhams</span></span></div>';
  }).join('');
  return '<div class="tally" style="margin-top:10px"><div class="row big"><span>Skippers\u2019 board — all crossings, every fate</span><span></span></div>' + rows + '</div>';
}
/* ---------- skippers’ board ---------- */
var BOARDAPI = 'https://xhruovtrxfsclfrgtezh.supabase.co/rest/v1/hmg_board';   // round 49: the far-shore board lives on Supabase; the publishable key below is public by design, everything else is enforced server-side
var SBAUTH = 'sb_publishable_L82ToLtxE7lnWlpiMxxP6Q_5IONSlAZ';
function sbEsc(x) { return String(x == null ? '' : x).replace(/&/g, '&' + 'amp;').replace(/</g, '&' + 'lt;').replace(/>/g, '&' + 'gt;').replace(/"/g, '&' + 'quot;'); }
function sbRank(row) {   // round 50: where this venture stands among the skippers who reached the same landing
  if (!BOARDAPI || !SBAUTH || !row) return;
  fetch(BOARDAPI + '?select=n,s&g=eq.' + encodeURIComponent(row.g) + '&order=s.desc&limit=200', { headers: { 'apikey': SBAUTH, 'Authorization': 'Bearer ' + SBAUTH } })
    .then(function (r) { return r.json(); })
    .then(function (rows) {
      rows = Array.isArray(rows) ? rows : [];
      var rank = 1, i = 0;
      while (i < rows.length && (rows[i].s | 0) >= row.s) { rank++; i++; }
      window.sbRankData = { g: row.g, s: row.s, rank: rank, total: rows.length + 1, top: rows.slice(0, 5) };
      if (S && S.phase === 'end') render();
    })
    .catch(function () {});
}
function sbPush(row) {
  if (!BOARDAPI || !SBAUTH || !row) return;
  fetch(BOARDAPI, { method: 'post', headers: { 'apikey': SBAUTH, 'Authorization': 'Bearer ' + SBAUTH, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify([row]) })
    .then(function (r) { if (r.ok) toast('Your run is rowed to the far-shore board.'); else toast('The far-shore board refused that log (' + r.status + ').'); })
    .catch(function () {});   // offline or blocked: the run is already safe in the local board
}
function sbPull(silent) {
  if (!silent) { window.sbMsg = 'Rowing to the far-shore board\u2026'; render(); }
  fetch(BOARDAPI + '?select=n,s,d,m,t,g&order=s.desc&limit=120', { headers: { 'apikey': SBAUTH, 'Authorization': 'Bearer ' + SBAUTH } })
    .then(function (r) { return r.json(); })
    .then(function (rows) { window.sbRows = (Array.isArray(rows) ? rows : []); window.sbMsg = ''; render(); })
    .catch(function () { window.sbRows = null; window.sbMsg = 'The far shore could not be reached \u2014 the shared board needs open water (a network).'; if (!silent) render(); });
}
function sharedHtml() {
  if (window.sbAuto !== 1 && !window.sbRows) { window.sbAuto = 1; sbPull(true); }   // round 50: quiet auto-pull, once per load
  var h = '<details style="margin-top:12px"><summary class="mut" style="font-size:13px">The skippers\u2019 far-shore board (all players)</summary>' +
    '<p class="mut" style="font-size:13px;margin:8px 0">Every finished run on the shared board of the road \u2014 the top twenty of each landing. Pull it below (needs the open water).</p>' +
    '<button class="small" onclick="sbPull()">Pull the far-shore board</button>' +
    (window.sbMsg ? '<p class="mut" style="font-size:13px;margin:6px 0">' + window.sbMsg + '</p>' : '');
  var rows = window.sbRows;
  if (!rows) return h + '</details>';
  var hubs = [['Miklagard', 'Miklagard \u2014 the Golden Horn'], ['Cherson', 'Cherson'], ['Kiev', 'Kiev'], ['Gnezdovo', 'Gnezdovo'], ['Holmgard', 'Holmgard'], ['Aldeigjuborg', 'Aldeigjuborg']];
  hubs.forEach(function (hb) {
    var sub = rows.filter(function (e) { return e.g === hb[0]; }).slice(0, 20);
    if (!sub.length) return;
    h += '<div class="tally" style="margin-top:8px"><div class="row big"><span>' + hb[1] + '</span><span></span></div>';
    sub.forEach(function (e, i) {
      h += '<div class="row"><span>' + (i + 1) + '. ' + sbEsc(e.n || 'The skipper') + '</span><span>' + (e.s | 0) + ' <span class="mut">\u2014 day ' + (e.d | 0) + ', ' + (e.m | 0) + ' marks</span></span></div>';
    });
    h += '</div>';
  });
  return h + '</details>';
}
var S = null;
var inTitle = true;
var inHelp = false;
var helpFrom = 'title';
var keepScroll = false;

function showHelp(from) { inHelp = true; helpFrom = from || (S && S.phase && S.phase !== 'end' ? 'game' : 'title'); render(); }
function closeHelp() { inHelp = false; if (helpFrom === 'game') { keepScroll = true; } render(); }
function viewHelp() {
  return '<div class="card contract help">' +
    '<h2 class="serif" style="margin-top:0">How to read the screen</h2>' +
    '<style>.help .terms div { margin: 16px 0; } .help .terms span { display: block; margin: 0 0 10px; }</style>' +
    '<div class="terms">' +
    '<div><span>Rations \u2014 top left</span>Food aboard. Your company \u2014 ten mouths when everyone lives \u2014 eats every day. When the pot runs dry the crew weakens first, then dies one by one. Smoking fish on a skerry or buying from locals refills it. A dead man eats nothing.</div>' +
    '<div><span>Silver \u2014 top</span>Money in the purse, counted in dirhams \u2014 the silver coins the river trade runs on. It buys fish, hull repairs, healing, hands and cargo. Salvage it: leftover silver adds to your score.</div>' +
    '<div><span>Hull \u2014 top</span>The boat\u2019s heartbeat. Storms, blind rocks and untreated leaks wound her; at zero she sinks with the cargo. Beaching and re-sealing her seams heals it.</div>' +
    '<div><span>Spirits \u2014 top</span>Crew mood. Overtaxed and starving men sour, and sour men make bad crossings; fresh food, good omens and rest raise spirits.</div>' +
    '<div><span>Journey length \u2014 the long bar</span>The bar empties each leg. First: Birka to Aldeigjuborg — near 500 sea-miles, a fair crossing 15\u201320 days. Second: upriver to Holmgard — near 120 miles, 15\u201320 days loaded. Every day\u2019s choices add distance: bold ones run, careful ones crawl. Losing hands slows the boat, because oars need backs.</div>' +
    '<div><span>The landing \u2014 between the legs</span>At Aldeigjuborg the cloth is scored and paid out. The hub screen follows: hire hands from the beach, load furs (2 dirhams, 1 hold unit) or a captive (4 dirhams, 2 hold units), or take a merchant\u2019s freight bale (free, 1 hold unit, pays 2 dirhams at Holmgard \u2014 good silver when the purse runs thin, but it crowds out furs), then cast off up the river. The hold fits 12 units.</div>' +
    '<div><span>Captives \u2014 hold and pot</span>A captive is cargo that eats: one ration a day, counted in the day\u2019s mouths. If the pot runs dry, the crew eats first, the captives go hungry, and the crew hears them (spirits drop). At the rapids, walking them round means one may bolt for the woods.</div>' +
    '<div><span>The southern road \u2014 the third leg</span>From Holmgard the water-road runs to Miklagard: the Lovat and the portage to Gnezdovo, down the Dnieper to Kiev, the rapids road to Cherson, then the Greek sea. Near 90 days \u2014 the June fleet clears Kiev early in July and the sea closes at Cherson in late August. Freight taken at Holmgard or Gnezdovo pays at Kiev; everything else scores at Miklagard. At Holmgard you can also sell leftover furs or captives to a factor (quick prices, into the purse), or buy fresh cargo for the southern venture. At Kiev the gathering\'s merchants pay quick silver too — 3 dirhams a bale for furs, 5 a head for captives — before the rapids road takes its toll. The rapids road below Kiev: warp through on lines, run under oar, or walk the cargo round — Nenasytets is the big one, and a captive on the chain-line may bolt. The Pecheneg summer is at peace, but a fumbled parley can cost a man; the cock sacrifice at the great island is worth its coin. The Greek sea: the summons seals at Cherson decide who sails, the treaty dromons escort what they can see — Mesembria has the last cheap bread, St Aitherios the last re-rig, and then the Horn. At Cherson the Greek market is open: a bale of wine, oil or glass costs 3 dirhams and 1 unit of hold — the factor pays 6 a bale at Miklagard, so spare hold and spare silver should become goods.</div>' +
    '<div><span>The convoy window \u2014 day 32 (May 11)</span>The thaw clears Ladoga and the early southbound convoys leave the landing. Arrive after day 32 and the buyer pays half; drag past day 44 and the Kiev road closes for good.</div>' +
    '<div><span>Names \u2014 chips under the bar</span>Your crew. Each is a person who lives or dies by your choices, and each death costs 10 dirhams of the settlement and slows the boat.</div>' +
    '</div>' +
    '<p class="mut" style="font-size:13px">Score at a leg\u2019s end: dirhams \u00d7 100 + living crew \u00d7 50 + every day ahead of the convoys \u00d7 25 + silver in hand \u00d7 20. The skippers\u2019 board tags each run with the destination reached: Aldeigjuborg or Holmgard.</p>' +
    '<button class="primary" onclick="closeHelp()">Back</button>' +
    '</div>';
}

function loadSlot() {
  var raw = SR.get(KEY);
  if (!raw) return null;
  try {
    var o = JSON.parse(raw);
    if (o && o.v === 2 && o.s) {
      if (o.b != null) SR.set(KEYB, o.b);   // the save slot is the durable copy of the board
      return o.s;
    }
    return o; // old format: plain run blob
  } catch (e) { return null; }
}

function newGame(seed) {
  var sd = seed || ((Date.now() & 0x7fffffff) || 1);
  SR.set(KEYS, String(sd));
  S = HMG.newRun(sd);
  inTitle = false;
  save();
  render();
}
function save() { SR.set(KEY, JSON.stringify({ v: 2, s: S, b: SR.get(KEYB) })); }
function toTitle() { inTitle = true; render(); }

